def permission_tests(matrix):
    return sorted((r, a, "allow" if ok else "deny") for (r, a), ok in matrix.items())

def negative_tests(matrix):
    return [t for t in permission_tests(matrix) if t[2] == "deny"]

tests.code:
perm = {("admin","delete"): True, ("editor","delete"): False, ("viewer","delete"): False, ("admin","edit"): True, ("editor","edit"): True, ("viewer","edit"): False}
t = permission_tests(perm)
assert ("viewer", "edit", "deny") in t and ("editor", "edit", "allow") in t

perm = {("admin","delete"): True, ("editor","delete"): False, ("viewer","delete"): False, ("admin","edit"): True, ("editor","edit"): True, ("viewer","edit"): False}
n = negative_tests(perm)
assert n == [("editor", "delete", "deny"), ("viewer", "delete", "deny"), ("viewer", "edit", "deny")], n
